import numpy as np
from scipy.optimize import least_squares
def base(p,e): return p[0]+p[1]*(1-np.exp(-p[2]*e))+p[3]*(1-np.exp(-p[4]*e**p[5]))
pb=np.array([-0.18459256,4.1692782,0.99232449,33.93104443,0.11563094,0.80771504])
variants={
 'T*exp(-c e)': (lambda p,e,t: base(p[:6],e)+p[6]*t*np.exp(-p[7]*e), [0.1,0.5]),
 'T*e*exp(-c e)': (lambda p,e,t: base(p[:6],e)+p[6]*t*e*np.exp(-p[7]*e), [0.1,0.5]),
 'exp(-c e/T)': (lambda p,e,t: base(p[:6],e)+p[6]*np.exp(-p[7]*e/t), [0.1,0.5]),
 'T-scaled eps': (lambda p,e,t: base(p[:6],e*(1+p[6]*t)), [0.0,0.0]),
 'e^(a T) term': (lambda p,e,t: base(p[:6],e)+p[6]*e**(p[7]*t), [0.1,0.5]),
}
for name,(fn,st) in variants.items():
    best=None
    for k in range(12):
        p0=np.concatenate([pb, np.array(st)+np.random.randn(2)*0.05*(k>0)])
